import 'package:cloud_firestore/cloud_firestore.dart';
import 'package:flutter/material.dart';
import '../../../app/atlas_academy_app.dart';
import 'student_mcq_practice_screen.dart';
import 'student_mcq_history_screen.dart';

class StudentMcqHubScreen extends StatelessWidget {
 const StudentMcqHubScreen({super.key});
 void _openSet(BuildContext context,String id){Navigator.push(context,MaterialPageRoute(builder:(_)=>StudentMcqPracticeScreen(examSetId:id)));}
 void _openHistory(BuildContext context){Navigator.push(context,MaterialPageRoute(builder:(_)=>const StudentMcqHistoryScreen()));}
 @override Widget build(BuildContext context)=>Scaffold(backgroundColor:AtlasColors.ivory,appBar:AppBar(title:const Text('MCQ Learning Centre'),backgroundColor:AtlasColors.navy,foregroundColor:Colors.white,elevation:0),body:ListView(padding:const EdgeInsets.all(18),children:[
 Container(padding:const EdgeInsets.all(22),decoration:BoxDecoration(gradient:const LinearGradient(colors:[AtlasColors.navy,AtlasColors.royalBlue,AtlasColors.brightBlue]),borderRadius:BorderRadius.circular(24)),child:const Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Icon(Icons.school_rounded,color:Colors.white,size:34),SizedBox(height:13),Text('Your Medical Exam Preparation',style:TextStyle(color:Colors.white,fontSize:21,fontWeight:FontWeight.w900)),SizedBox(height:7),Text('Choose an MBBS subject or licensing pathway, then open a published exam set.',style:TextStyle(color:Colors.white70,height:1.5))])),
 const SizedBox(height:22),
 Row(children:[const Expanded(child:Text('Published Exam Sets',style:TextStyle(color:AtlasColors.navy,fontSize:19,fontWeight:FontWeight.w900))),TextButton.icon(onPressed:()=>_openHistory(context),icon:const Icon(Icons.history),label:const Text('History'))]),
 StreamBuilder<QuerySnapshot<Map<String,dynamic>>>(stream:FirebaseFirestore.instance.collection('mcq_exam_sets').where('trackType',isEqualTo:'mbbs').where('isPublished',isEqualTo:true).snapshots(),builder:(context,s){if(s.hasError)return const Padding(padding:EdgeInsets.all(18),child:Text('Unable to load exam sets. Please try again later.'));if(!s.hasData)return const Padding(padding:EdgeInsets.all(24),child:Center(child:CircularProgressIndicator()));final docs=s.data!.docs;if(docs.isEmpty)return Container(padding:const EdgeInsets.all(24),decoration:BoxDecoration(color:Colors.white,borderRadius:BorderRadius.circular(18)),child:const Column(children:[Icon(Icons.library_books_outlined,size:42,color:AtlasColors.royalBlue),SizedBox(height:10),Text('No exams published yet',style:TextStyle(fontWeight:FontWeight.w900,color:AtlasColors.navy)),SizedBox(height:5),Text('Your academy will add exam sets here when they are ready.',textAlign:TextAlign.center,style:TextStyle(color:AtlasColors.secondaryText))]));return Column(children:docs.map((d){final x=d.data();final track='MBBS';final parent=track=='MBBS'?(x['yearName']??'MBBS'):(x['pathwayName']??'Licensing');final subject=x['subjectName']??'Subject';return Container(margin:const EdgeInsets.only(bottom:12),decoration:BoxDecoration(color:Colors.white,borderRadius:BorderRadius.circular(18),border:Border.all(color:AtlasColors.border)),child:ListTile(contentPadding:const EdgeInsets.symmetric(horizontal:16,vertical:8),leading:Container(width:46,height:46,decoration:BoxDecoration(color:AtlasColors.royalBlue.withValues(alpha:.1),borderRadius:BorderRadius.circular(14)),child:const Icon(Icons.quiz_rounded,color:AtlasColors.royalBlue)),title:Text((x['name']??'Exam set').toString(),style:const TextStyle(fontWeight:FontWeight.w900,color:AtlasColors.navy)),subtitle:Text('$track • $parent\n$subject',style:const TextStyle(color:AtlasColors.secondaryText,height:1.5)),isThreeLine:true,trailing:const Icon(Icons.arrow_forward_ios_rounded,size:16),onTap:()=>_openSet(context,d.id)));}).toList());}),
 const SizedBox(height:16),const Center(child:Text('THE ATLAS ACADEMY',style:TextStyle(color:AtlasColors.navy,fontSize:10,letterSpacing:1.5,fontWeight:FontWeight.w900)))
 ]));
}
